namespace ghidra.app.cmd.module;

using ghidra.framework.cmd;
using ghidra.program.model.listing;
using ghidra.util.exception;

/**
 * Command for renaming a fragment or a module in listing.
 * 
 * 
 */
public class RenameCmd : Command<Program> {

	private string oldName;
	private string newName;
	private bool isModule;
	private string cmdName;
	private string statusMsg;
	private string treeName;
	private bool ignoreDuplicateName;

	/** 
	 * Construct a new RenameCmd.
	 * @param treeName name of the tree where the module or fragment resides
	 * @param isModule true if a module is to be renamed
	 * @param oldName current name of the module or fragment
	 * @param newName new name for the module or fragment
	 * @param ignoreDuplicateName true means to ignore the exception and
	 * don't do anything
	 */
	public RenameCmd(string treeName, bool isModule, string oldName, string newName,
			bool ignoreDuplicateName) {
		this.treeName = treeName;
		this.isModule = isModule;
		this.oldName = oldName;
		this.newName = newName;
		this.ignoreDuplicateName = ignoreDuplicateName;
		if (isModule) {
			cmdName = "Rename Folder";
		}
		else {
			cmdName = "Rename Fragment";
		}
	}

	/**
	 * Construct a new RenameCmd.
	 * @param treeName name of the tree where the module or fragment resides
	 * @param isModule true if a module is to be renamed
	 * @param oldName current name of the module or fragment
	 * @param newName new name for the module or fragment
	 */
	public RenameCmd(string treeName, bool isModule, string oldName, string newName) : this(treeName, isModule, oldName, newName, false)
    {
	}

	/* @Override */
	public bool applyTo(Program program) {
		return setName(program, oldName, newName);
	}

	/* @Override */
	public string getStatusMsg() {
		return statusMsg;
	}

	/* @Override */
	public string getName() {
		return cmdName;
	}

	private bool setName(Program program, string oldN, string newN) {
		Listing listing = program.getListing();
		try {
			if (isModule) {
				ProgramModule m = listing.getModule(treeName, oldN);
				m.setName(newN);
			}
			else {
				ProgramFragment f = listing.getFragment(treeName, oldN);
				f.setName(newN);
			}
			return true;
		}
		catch (DuplicateNameException e) {
			if (ignoreDuplicateName) {
				newName = oldName;
				return true;
			}
			statusMsg = "Name already exists for " + newN;
		}
		return false;
	}

}
